{
 "path": "/home/USER/continual-arc-baselines/.workbench/stage1/HPL0-hermes-luna6-medium-rnd0/frozen/held-out/play/users/u000/system/state/workspace/programs/task-f392fc85.py",
 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    tile = 3 if h == 11 else 4
    pitch = tile + 1
    nrows = (h + 1) // pitch
    ncols = (w + 1) // pitch

    # The 3-colored area is a masked tile region. Clear it, then infer the
    # diagonal hidden tile in a horizontal mask from the first panel; for a
    # vertical mask, the hidden tile is the difference of the two known tiles.
    three_rows = [r for r in range(h) if all(v == 3 for v in grid[r])]
    three_cols = [c for c in range(w) if all(grid[r][c] == 3 for r in range(h))]
    for r in range(h):
        for c in range(w):
            if out[r][c] == 3:
                out[r][c] = 0

    if three_rows:
        r0 = min(three_rows)
        tr = r0 // pitch
        tc = tr
        if tr < nrows and tc < ncols:
            src_r = 0
            src_c = tc * pitch
            dst_r = tr * pitch
            dst_c = tc * pitch
            if src_r + tile <= h and src_c + tile <= w and dst_r + tile <= h and dst_c + tile <= w:
                for dr in range(tile):
                    for dc in range(tile):
                        out[dst_r + dr][dst_c + dc] = grid[src_r + dr][src_c + dc]
    elif three_cols:
        c0 = min(three_cols)
        tc = c0 // pitch
        if tc == ncols - 1:
            for tr in range(nrows):
                r0 = tr * pitch
                c_dst = tc * pitch
                c_left = 0
                c_mid = pitch
                if r0 + tile > h or c_dst + tile > w or c_mid + tile > w:
                    continue
                for dr in range(tile):
                    for dc in range(tile):
                        # Set subtraction: retain cells present in the first
                        # tile and absent from the second.
                        out[r0 + dr][c_dst + dc] = int(
                            grid[r0 + dr][c_left + dc] == 2 and
                            grid[r0 + dr][c_mid + dc] != 2
                        ) * 2

    # Highlight the cell inside each glyph whose local coordinates match
    # the glyph's position in the macro-grid.
    for tr in range(nrows):
