    pitch = size + 1
    out = [row[:] for row in grid]

    # Erase the green stripe; it marks a missing panel row/column.
    for r in range(h):
        for c in range(len(grid[r])):
            if out[r][c] == 3:
                out[r][c] = 0

    # In the 19x19 arrangement, the missing middle row of motifs can be
    # recovered from the corresponding row of the lower panel. Restore the
    # visible glyph positions in that masked row based on the lower-panel
    # motif pattern (the input's target row has index 2).
    if h == 19:
        for tc in range(4):
            # Lower panel glyphs are at rows 15..18 and columns 5*tc..+3.
            sr, sc = 15, 5 * tc
            # infer which lower-panel cells represent the middle row glyph
            # using the marker cell at row 2 of each glyph
            if grid[sr + 2][sc + 2] == 2:
                for dr in range(4):
                    for dc in range(4):
                        out[10 + dr][sc + dc] = grid[sr + dr][sc + dc]

    # Recolor each motif's indexed occupied cell in the complete array.
    nrows, ncols = (h + 1) // pitch, (w + 1) // pitch
    for tr in range(nrows):
        for tc in range(ncols):
            rr, cc = tr * pitch + tr, tc * pitch + tc
            if rr < h and cc < w and out[rr][cc] == 2:
                out[rr][cc] = 8
    return out

