 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    size = 4 if h == 19 else 3
    pitch = size + 1
    nrows, ncols = (h + 1) // pitch, (w + 1) // pitch
    motif = [row[:size] for row in grid[:size]]
    out = [[0 for _ in range(w)] for _ in range(h)]

    # The motif is also the macro-grid occupancy map. Tile a copy of it at
    # every macro-coordinate whose corresponding motif cell is occupied.
    for tr in range(min(size, nrows)):
        for tc in range(min(size, ncols)):
            if motif[tr][tc] != 2:
                continue
            r0, c0 = tr * pitch, tc * pitch
            for dr in range(size):
                for dc in range(size):
                    if r0 + dr < h and c0 + dc < w:
                        out[r0 + dr][c0 + dc] = motif[dr][dc]
            out[r0 + tr][c0 + tc] = 8
    return out

